// === API Key auth ===
var apiKey = global.get("edge_apiKey");
if (!apiKey) { msg.payload = { error: 'edge_apiKey not configured' }; msg.statusCode = 500; return msg; }
var reqKey = (msg.req && msg.req.headers && msg.req.headers["x-api-key"]) || "";
if (reqKey !== apiKey) {
    msg.payload = { error: "Unauthorized" };
    msg.statusCode = 401;
    return msg;
}
var nodeId = global.get('edge_nodeId') || 0;
var hostPcIp = global.get('edge_hostPcIp') || '127.0.0.1';
var devices = global.get('edge_devices') || [];
var commStatus = global.get('edge_commStatus') || {};
var configReady = global.get('edge_configReady') || false;
var startTime = global.get('edge_startTime');
if (!startTime) { startTime = new Date().toISOString(); global.set('edge_startTime', startTime); }
var mem = 0;
try { var pr = global.get('process'); mem = pr ? parseFloat((pr.memoryUsage().rss / 1024 / 1024).toFixed(1)) : 0; } catch (e) { mem = 0; }

var deviceList = devices.map(function (d) {
    var s = commStatus[d.id] || {};
    return {
        id: d.id, name: d.deviceName, comType: d.comType,
        plcIp: d.plcIp, plcPort: d.plcPort,
        online: (s.consecutiveFails || 0) === 0,
        consecutiveFails: s.consecutiveFails || 0,
        tagCount: (d.tags || []).length
    };
});
var uptime = Math.floor((Date.now() - new Date(startTime).getTime()) / 1000);
var pgSuccessCount = global.get('edge_pg_success_count') || 0;
var pgFailCount = global.get('edge_pg_fail_count') || 0;
var pgLatency = global.get('edge_pg_last_latency_ms') || 0;
var pgLastError = global.get('edge_pg_last_error') || '';
var pgLastWrite = global.get('edge_pg_last_write_ts') || '';
var pgWriting = global.get('edge_pg_writing') || false;
var lastConfigRefresh = global.get('edge_last_config_ts') || '';
msg.payload = {
    nodeId: nodeId, hostPcIp: hostPcIp,
    configReady: configReady, uptimeSeconds: uptime, memoryUsageMb: mem,
    deviceCount: devices.length,
    onlineCount: deviceList.filter(function (d) { return d.online; }).length,
    devices: deviceList,
    pgQueueSize: (global.get('edge_pg_queue') || []).length,
    pgSuccessCount: pgSuccessCount,
    pgFailCount: pgFailCount,
    pgLatencyMs: pgLatency,
    pgLastError: pgLastError,
    pgLastWriteTs: pgLastWrite,
    pgWriting: pgWriting,
    lastConfigRefresh: lastConfigRefresh,
    ts: new Date().toISOString()
};
return msg;

// === API Key auth ===
var apiKey = global.get("edge_apiKey");
if (!apiKey) { msg.payload = { error: 'edge_apiKey not configured' }; msg.statusCode = 500; return msg; }
var reqKey = (msg.req && msg.req.headers && msg.req.headers["x-api-key"]) || "";
if (reqKey !== apiKey) {
    msg.payload = { error: "Unauthorized" };
    msg.statusCode = 401;
    return msg;
}
var deviceId = parseInt(msg.req.params.id);
var devices = global.get('edge_devices') || [];
var lastGoodTags = global.get('edge_lastGoodTags') || {};
var commStatus = global.get('edge_commStatus') || {};

var device = null;
for (var i = 0; i < devices.length; i++) {
    if (devices[i].id === deviceId) { device = devices[i]; break; }
}
if (!device) {
    msg.payload = { error: 'Device not found' };
    msg.statusCode = 404;
    return msg;
}
var status = commStatus[deviceId] || {};
var tags = lastGoodTags[deviceId] || [];
msg.payload = {
    id: device.id, name: device.deviceName,
    comType: device.comType, plcIp: device.plcIp, plcPort: device.plcPort,
    online: (status.consecutiveFails || 0) === 0,
    consecutiveFails: status.consecutiveFails || 0,
    tagCount: (device.tags || []).length,
    latestValues: tags,
    ts: new Date().toISOString()
};
return msg;

// === API Key auth ===
var apiKey = global.get("edge_apiKey");
if (!apiKey) { msg.payload = { error: 'edge_apiKey not configured' }; msg.statusCode = 500; return msg; }
var reqKey = (msg.req && msg.req.headers && msg.req.headers["x-api-key"]) || "";
if (reqKey !== apiKey) {
    msg.payload = { error: "Unauthorized" };
    msg.statusCode = 401;
    return msg;
}
var alerts = global.get('edge_recentAlerts') || [];
msg.payload = {
    alerts: alerts.slice(-10).reverse(),
    ts: new Date().toISOString()
};
return msg;

// === API Key auth ===
var apiKey = global.get("edge_apiKey");
if (!apiKey) { msg.payload = { error: 'edge_apiKey not configured' }; msg.statusCode = 500; return msg; }
var reqKey = (msg.req && msg.req.headers && msg.req.headers["x-api-key"]) || "";
if (reqKey !== apiKey) {
    msg.payload = { error: "Unauthorized" };
    msg.statusCode = 401;
    return msg;
}
var deviceId = parseInt(msg.req.params.deviceId);
var tagId = parseInt(msg.req.params.tagId);
var limit = parseInt(msg.req.query.limit) || 300;
var history = global.get('edge_historyData') || {};
var devHistory = history[deviceId] || {};
var tagHistory = devHistory[tagId] || [];
msg.payload = {
    deviceId: deviceId, tagId: tagId,
    points: tagHistory.slice(-limit)
};
return msg;

// === API Key auth ===
var apiKey = global.get("edge_apiKey");
if (!apiKey) { msg.payload = { error: 'edge_apiKey not configured' }; msg.statusCode = 500; return msg; }
var reqKey = (msg.req && msg.req.headers && msg.req.headers["x-api-key"]) || "";
if (reqKey !== apiKey) {
    msg.payload = { error: "Unauthorized" };
    msg.statusCode = 401;
    return msg;
}
var body = {};
try { body = msg.payload ? JSON.parse(typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload)) : {}; } catch (e) {}
var deviceId = body.deviceId || parseInt((msg.req.query || {}).deviceId) || 0;

if (deviceId <= 0) {
    msg.payload = { ok: false, error: 'deviceId is required (must be > 0)' };
    msg.statusCode = 400;
    return msg;
}
var la = global.get('edge_lastAlarmTime') || {};
delete la['dev_' + deviceId];
global.set('edge_lastAlarmTime', la);
var ra = global.get('edge_recentAlerts') || [];
global.set('edge_recentAlerts', ra.filter(function (a) { return a.deviceId !== deviceId; }));

msg.payload = { ok: true, deviceId: deviceId };
return msg;

// === API Key auth ===
var apiKey = global.get("edge_apiKey");
if (!apiKey) { msg.payload = { error: 'edge_apiKey not configured' }; msg.statusCode = 500; return msg; }
var reqKey = (msg.req && msg.req.headers && msg.req.headers["x-api-key"]) || "";
if (reqKey !== apiKey) {
    msg.payload = { error: "Unauthorized" };
    msg.statusCode = 401;
    return msg;
}
// Clear JWT → trigger full re-login in sf-config-manager
global.set('edge_jwt', '');
global.set('edge_configReady', false);
msg.payload = { ok: true, msg: 'Config refresh triggered' };
// Output 0: HTTP response, Output 1: reauth signal to sf-config-manager
return [msg, { payload: { action: 'reauth' } }];

// === sf-data-processor v10: 换算 + 死区 + 质量码 + 历史 + 双输出 ===
var result = msg.payload;
if (!result) { node.send([null, null]); return; }

var DEBUG = global.get('edge_debug') || false;

// === Per-device processing guard (prevents read-modify-write race) ===
var procGuard = global.get('edge_proc_guard') || {};
var guardEntry = procGuard[result.deviceId];
// If locked but expired (>30s), force release (uncaught exception recovery)
if (guardEntry && (Date.now() - guardEntry.ts > 30000)) {
    delete procGuard[result.deviceId];
    guardEntry = undefined;
}
if (guardEntry) {
    // 🔧 Drop duplicate — scheduler will re-collect this device next cycle
    if (DEBUG) node.warn('[DP] ProcGuard locked for device ' + result.deviceId + ', dropping duplicate');
    return;
}
procGuard[result.deviceId] = { ts: Date.now() };

try {
var nodeId = global.get('edge_nodeId') || 999;
var hostPcIp = global.get('edge_hostPcIp') || '127.0.0.1';
var tagConfigs = global.get('edge_tagConfigs') || {};
var devTags = tagConfigs[result.deviceId] || [];
var now = new Date().toISOString();
var nowMs = Date.now();

// === State references ===
var lastGoodTags = global.get('edge_lastGoodTags') || {};
var historyData = global.get('edge_historyData') || {};
var commStatus = global.get('edge_commStatus') || {};
var commPending = global.get('edge_commPending') || [];
var lastBadSend = global.get('edge_lastBadSend') || {};

var devId = result.deviceId;
var devName = result.deviceName || ('PLC-' + devId);
// 获取设备 triggerKind（0=握手 1=固定周期 2=变化触发）
var devices = global.get('edge_devices') || [];
var devInfo = null;
for (var di = 0; di < devices.length; di++) {
    if (devices[di].id === devId) { devInfo = devices[di]; break; }
}
var triggerKind = devInfo ? (devInfo.triggerKind || 1) : 1;

// ===== FAILURE PATH =====
if (!result.success) {
    var status = commStatus[devId] || { consecutiveFails: 0, lastState: 'online' };
    status.consecutiveFails = (status.consecutiveFails || 0) + 1;
    status.lastFailTime = nowMs;

    // P0-3: Only push to pending on state change (online → offline)
    if (status.lastState !== 'offline') {
        status.lastState = 'offline';
        commPending.push({
            deviceId: devId,
            success: false,
            error: result.error || 'communication failure',
            consecutiveFails: status.consecutiveFails,
            ts: now
        });
        global.set('edge_commPending', commPending);
        if (DEBUG) node.warn('[DP] Device ' + devName + ' state: online → offline');
        // Publish PLC_OFFLINE alarm via MQTT (v9.1 parity)
        var alarmMsg = {
            topic: 'edgelink/alarm/plc_offline/' + devId,
            payload: JSON.stringify({
                alert_type: 'PLC_OFFLINE',
                node_id: nodeId,
                device_id: devId,
                device_name: devName,
                host_pc_ip: hostPcIp,
                msg: devName + ' communication failure: ' + (result.error || 'unknown'),
                ts: now
            }),
            qos: 1,
            retain: false
        };
        var alerts = global.get('edge_recentAlerts') || [];
        alerts.push({
            alertType: 'PLC_OFFLINE',
            deviceId: devId,
            deviceName: devName,
            msg: result.error || 'communication failure',
            ts: now
        });
        if (alerts.length > 20) alerts = alerts.slice(-20);
        global.set('edge_recentAlerts', alerts);
    }
    commStatus[devId] = status;
    global.set('edge_commStatus', commStatus);

    // Re-publish last-good values with BAD quality (throttled: max every 30s)
    var shouldSendBad = !lastBadSend[devId] || (nowMs - lastBadSend[devId] > 30000);
    var mqttMsg = null;
    if (shouldSendBad && lastGoodTags[devId] && lastGoodTags[devId].length > 0) {
        lastBadSend[devId] = nowMs;
        global.set('edge_lastBadSend', lastBadSend);
        var badVals = JSON.parse(JSON.stringify(lastGoodTags[devId]));
        badVals.forEach(function (v) { v.quality = 'BAD'; });
        mqttMsg = {
            topic: 'edgelink/data/' + nodeId + '/' + devId,
            payload: JSON.stringify({
                node_id: nodeId,
                device_id: devId,
                device_name: devName,
                host_pc_ip: hostPcIp,
                ts: now,
                value_count: badVals.length,
                values: badVals,
                quality: 'BAD'
            }),
            qos: 1,
            retain: false
        };
    }

    delete procGuard[devId];
    global.set('edge_proc_guard', procGuard);
    // Send alarm + BAD data as array so mqtt-out publishes both
    // 🔧 修复#2：mqttOut 直接嵌进输出数组会变成"数组当消息"（mqtt-out 拿不到 topic 丢失）——嵌套一层逐条扇出
    var mqttOut = alarmMsg ? (mqttMsg ? [alarmMsg, mqttMsg] : [alarmMsg]) : (mqttMsg ? [mqttMsg] : []);
    node.send([mqttOut.length ? mqttOut : null, null]);
    node.status({ fill: 'red', shape: 'ring', text: devName + ' OFFLINE' });
    return;
}

// ===== SUCCESS PATH =====

// Reset comm status on success
var prevStatus = commStatus[devId] || { consecutiveFails: 0, lastState: 'online' };
var wasOffline = prevStatus.lastState === 'offline';
commStatus[devId] = { consecutiveFails: 0, lastState: 'online', lastSuccessTime: nowMs };
global.set('edge_commStatus', commStatus);

// P0-3: Push to pending on recovery (offline → online)
if (wasOffline) {
    commPending.push({
        deviceId: devId,
        success: true,
        error: '',
        consecutiveFails: 0,
        ts: now
    });
    global.set('edge_commPending', commPending);
    if (DEBUG) node.warn('[DP] Device ' + devName + ' state: offline → online (recovered)');
}

var stdData = result.data || {};
var tagValues = [];
var pgRecords = [];
var validCount = 0;
var skippedCount = 0;

// Process each tag
(devTags.length > 0 ? devTags : []).forEach(function (tag) {
    var entry = stdData[tag.id];
    if (!entry || entry.rawValue === undefined || entry.rawValue === null) {
        // Tag not in this read, mark as missing
        tagValues.push({
            tag_id: tag.id,
            tag_address: tag.regAddr || '',
            tag_name: tag.name || '',
            raw_value: null,
            eng_value: null,
            unit: tag.unit || '',
            quality: 'UNCERTAIN',
            ts: now
        });
        return;
    }

    // Step 1: Transform (linear: y=a·x+b; slope_offset: 量程映射)
    var eng = entry.rawValue;
    var tform = tag.tform || tag.transformType || 'none';
    var quality = entry.quality || 'GOOD';
    if (typeof quality === 'number') {
        quality = quality === 0 ? 'GOOD' : (quality === 1 ? 'BAD' : 'UNCERTAIN');
    }
    if (tform === 'linear') {
        // 🔧 Day5: slope=0 合法，不能用 || 兜底
        var _slope = (tag.slope !== undefined && tag.slope !== null) ? tag.slope : ((tag.transformSlopeA !== undefined && tag.transformSlopeA !== null) ? tag.transformSlopeA : 1);
        var _offset = (tag.offset !== undefined && tag.offset !== null) ? tag.offset : ((tag.transformOffsetB !== undefined && tag.transformOffsetB !== null) ? tag.transformOffsetB : 0);
        eng = entry.rawValue * _slope + _offset;
    } else if (tform === 'slope_offset') {
        var rawMin = tag.rawValueMin;
        var rawMax = tag.rawValueMax;
        var engMin = tag.engValueMin;
        var engMax = tag.engValueMax;
        if (rawMin == null || rawMax == null || engMin == null || engMax == null || rawMin === rawMax) {
            quality = 'UNCERTAIN';
            eng = entry.rawValue;
        } else {
            var ratio = (entry.rawValue - rawMin) / (rawMax - rawMin);
            eng = engMin + ratio * (engMax - engMin);
        }
    }
    eng = parseFloat(parseFloat(eng).toFixed(2));

    // Step 2: Deadband filtering（数值死区：abs(eng - prev) < deadband）
    var prevVals = lastGoodTags[devId] || [];
    var prev = null;
    for (var pi = 0; pi < prevVals.length; pi++) {
        if (prevVals[pi].tag_id === tag.id) { prev = prevVals[pi]; break; }
    }
    var deadband = tag.deadband || 0;
    var forceInterval = tag.reportForceIntervalMs || 5000;

    // triggerKind=2 变化触发：值未变化则跳过
    if (triggerKind === 2 && prev) {
        var prevEng = prev.eng_value;
        if (prevEng !== null && prevEng !== undefined && Math.abs(eng - prevEng) < 0.0001) {
            skippedCount++;
            return;
        }
    }

    if (prev && deadband > 0) {
        var delta = Math.abs(eng - (prev.eng_value || 0));
        var prevTs = prev.ts ? new Date(prev.ts).getTime() : 0;
        if (delta < deadband && (nowMs - prevTs) < forceInterval) {
            skippedCount++;
            return; // Skip: value within deadband, not forced yet
        }
    }

    // Step 3: Quality code 已在 Step 1 中统一处理

    var tv = {
        tag_id: tag.id,
        tag_address: tag.regAddr || '',
        tag_name: tag.name || '',
        raw_value: entry.rawValue,
        register_type: tag.regType || '',
        eng_value: eng,
        unit: tag.unit || '',
        quality: quality,
        ts: now
    };
    tagValues.push(tv);
    validCount++;

    // Step 4: PG record
    pgRecords.push({
        ts: now,
        node_id: nodeId,
        device_id: devId,
        device_name: devName,
        tag_id: tag.id,
        tag_address: tag.regAddr || '',
        tag_name: tag.name || '',
        raw_value: entry.rawValue,
        register_type: tag.regType || '',
        eng_value: eng,
        unit: tag.unit || '',
        quality: quality,
        host_pc_ip: hostPcIp
    });

    // Step 5: History cache
    if (!historyData[devId]) historyData[devId] = {};
    if (!historyData[devId][tag.id]) historyData[devId][tag.id] = [];
    historyData[devId][tag.id].push({ ts: now, raw: entry.rawValue, eng: eng, q: quality });
    if (historyData[devId][tag.id].length > 100) {
        historyData[devId][tag.id] = historyData[devId][tag.id].slice(-100);
    }
});

// === 计算点位（派生点位）：值=同设备来源点位的 和/平均/最大/最小（源失效用最近有效值续算） ===
var calcTagList = (devInfo && devInfo.calcTags) || [];
calcTagList.forEach(function (ct) {
    var prevGoodList = lastGoodTags[devId] || [];
    var vals = [];
    var anyStale = false;
    (ct.sourceIds || []).forEach(function (sid) {
        var v = null;
        var vq = null;
        for (var fi = 0; fi < tagValues.length; fi++) {
            if (tagValues[fi].tag_id === sid) { v = tagValues[fi].eng_value; vq = tagValues[fi].quality; break; }
        }
        if (v === null || v === undefined) {
            for (var pj = 0; pj < prevGoodList.length; pj++) {
                if (prevGoodList[pj].tag_id === sid) { v = prevGoodList[pj].eng_value; vq = prevGoodList[pj].quality; break; }
            }
        }
        if (v !== null && v !== undefined) {
            vals.push(v);
            if (vq !== 'GOOD') anyStale = true;
        }
    });
    if (vals.length === 0) {
        return;  // 所有来源从未有值：本轮跳过
    }
    var calc = 0;
    if (ct.calcOp === 'avg') {
        vals.forEach(function (x) { calc += x; });
        calc = calc / vals.length;
    } else if (ct.calcOp === 'min') {
        calc = Math.min.apply(null, vals);
    } else if (ct.calcOp === 'max') {
        calc = Math.max.apply(null, vals);
    } else {
        vals.forEach(function (x) { calc += x; });  // sum 默认
    }
    calc = parseFloat(parseFloat(calc).toFixed(2));
    var calcQuality = (anyStale || vals.length < (ct.sourceIds || []).length) ? 'UNCERTAIN' : 'GOOD';

    // 与采集点位同一过滤管道：变化触发 / 数值死区
    // 🔧 变化判定用独立 edge_lastCalc 记录上一次计算值——lastGoodTags 的合并只收 GOOD 质量位，
    //    计算点位因源点位未本轮刷新而常带 UNCERTAIN，会永远进不了 lastGood，导致与过期值比较而重复插入
    var lastCalc = global.get('edge_lastCalc') || {};
    var prevCalcEng = (lastCalc[ct.id] !== undefined) ? lastCalc[ct.id] : null;
    var prevCalcTs = lastCalc[ct.id + '_ts'] || 0;
    if (triggerKind === 2 && prevCalcEng !== null) {
        if (Math.abs(calc - prevCalcEng) < 0.0001) {
            skippedCount++;
            return;
        }
    }
    var calcDeadband = ct.deadband || 0;
    var calcForce = ct.reportForceIntervalMs || 5000;
    if (prevCalcEng !== null && calcDeadband > 0) {
        var calcDelta = Math.abs(calc - prevCalcEng);
        if (calcDelta < calcDeadband && (nowMs - prevCalcTs) < calcForce) {
            skippedCount++;
            return;
        }
    }
    lastCalc[ct.id] = calc;
    lastCalc[ct.id + '_ts'] = nowMs;
    global.set('edge_lastCalc', lastCalc);

    var ctv = {
        tag_id: ct.id, tag_address: 'CALC', tag_name: ct.name || '',
        raw_value: calc, register_type: 'CALC', eng_value: calc,
        unit: ct.unit || '', quality: calcQuality, ts: now
    };
    tagValues.push(ctv);
    validCount++;
    pgRecords.push({
        ts: now, node_id: nodeId, device_id: devId, device_name: devName,
        tag_id: ct.id, tag_address: 'CALC', tag_name: ct.name || '',
        raw_value: calc, register_type: 'CALC', eng_value: calc,
        unit: ct.unit || '', quality: calcQuality, host_pc_ip: hostPcIp
    });
});

// Update lastGoodTags — 🔧 合并更新 + 标记未读到tag为quality=2
var prevGood = lastGoodTags[devId] || [];
var newGood = tagValues.filter(function (v) { return v.quality === 'GOOD'; });  // 🔧 Day5: 质量码是字符串，!==2 永真导致坏值污染 lastGood；只保留 GOOD
var prevMap = {};
// Mark all previous as stale (quality=2), then overwrite with fresh reads
prevGood.forEach(function (pg) {
    prevMap[pg.tag_id] = { tag_id: pg.tag_id, tag_address: pg.tag_address, tag_name: pg.tag_name,
        raw_value: pg.raw_value, eng_value: pg.eng_value, unit: pg.unit,
        quality: 'UNCERTAIN', ts: pg.ts };  // 🔧 Day5: stale 标记用字符串（全链质量码词汇统一 OPC UA 语义）
});
newGood.forEach(function (ng) { prevMap[ng.tag_id] = ng; });
var merged = [];
for (var k in prevMap) {
    if (Object.prototype.hasOwnProperty.call(prevMap, k)) merged.push(prevMap[k]);
}
lastGoodTags[devId] = merged;
global.set("edge_lastGoodTags", lastGoodTags);
global.set("edge_historyData", historyData);

// PG success counter is incremented by sf-pg-writer after successful write only

// === Build outputs ===
var mqttMsg = null;
if (tagValues.length > 0) {
    mqttMsg = {
        topic: 'edgelink/data/' + nodeId + '/' + devId,
        payload: JSON.stringify({
            node_id: nodeId,
            device_id: devId,
            device_name: devName,
            host_pc_ip: hostPcIp,
            ts: now,
            value_count: validCount,
            values: tagValues
        }),
        qos: 1,
        retain: false
    };
}

var pgMsg = null;
if (pgRecords.length > 0) {
    pgMsg = { payload: { pgRecords: pgRecords } };
}

if (DEBUG && validCount > 0) {
    node.status({ fill: 'green', shape: 'dot', text: devName + ' ' + validCount + ' vals' + (skippedCount > 0 ? ' (' + skippedCount + ' skipped)' : '') });
}

} finally {
delete procGuard[devId];
global.set('edge_proc_guard', procGuard);
}
node.send([mqttMsg, pgMsg]);
return;

// === sf-config-manager Step 1: IP检测 + 单例锁 + 分路径 + 登录请求 ===
var DEBUG = global.get('edge_debug') || false;
var isReauth = (msg.payload && msg.payload.action === 'reauth');
var existingJwt = global.get('edge_jwt') || '';

// === Singleton lock (60s expiry) ===
var lock = global.get('edge_config_manager_lock');
if (lock && (Date.now() - lock.ts < 60000)) {
    if (isReauth) {
        // Reauth: wait until current init finishes (max 30s)
        if (Date.now() - lock.ts < 30000) {
            if (DEBUG) node.warn('[CM] Re-auth waiting for active init (' + (Date.now() - lock.ts) + 'ms old)');
            setTimeout(function () { node.send(msg); }, 2000);
            return null;
        }
        // Force takeover after 30s
