if (!global.get('edge_configReady')) {
    node.status({ fill: 'grey', shape: 'dot', text: 'wait config' });
    return [null, null];
}

// === Memory usage ===
var mem = 0;
try { var pr = global.get('process'); mem = pr ? Math.round(pr.memoryUsage().rss / 1024 / 1024) : 0; } catch (e) { mem = 0; }

// === Build MQTT heartbeat (Output 1) ===
// === 所有设备定期上报 online（修复离线判定滞后）===
function reportAllDevicesOnline() {
    var devs = global.get('edge_devices') || [];
    var commStat = global.get('edge_commStatus') || {};
    try {
    devs.forEach(function(d) {
        var cs = commStat[d.id] || {};
        // 有最近成功记录且连续失败为0 → online
        var ok = (cs.consecutiveFails || 0) === 0 && cs.lastSuccessTime;
        // 每个设备单独上报
        var dp = 'node_id=' + encodeURIComponent(nodeId) + '&device_id=' + encodeURIComponent(d.id)
            + '&success=' + (ok ? 'true' : 'false')
            + '&error_msg=' + encodeURIComponent(ok ? '' : 'no recent success');
        var opts = {
            hostname: HOST, port: PORT, path: '/monitor/device-comm?' + dp, method: 'POST',
            headers: { 'X-API-Key': apiKey, 'Authorization': 'Bearer ' + jwt, 'Content-Type': 'application/json' }
        };
        var r = http.request(opts, function(res) { res.resume(); });
        r.setTimeout(2000, function() { r.destroy(); });
        r.on('error', function() {});
        r.write('{}');
        r.end();
    });
    if (DEBUG && devs.length > 0) node.warn('[Monitor] Reported ' + devs.length + ' devices online');
    } catch(ex) { node.warn('[Monitor] reportAllDevicesOnline error: ' + ex.message); }
}

var devList = devices.map(function (d) {
    var status = (global.get('edge_commStatus') || {})[d.id] || {};
    return {
        id: d.id, name: d.deviceName,
        online: (status.consecutiveFails || 0) === 0,
        consecutiveFails: status.consecutiveFails || 0,
        tagCount: (d.tags || []).length
    };
});

var mqttMsg = {
    topic: 'edgelink/heartbeat/' + nodeId,
    payload: JSON.stringify({
        node_id: nodeId, host_pc_ip: hostPcIp,
        device_count: devices.length, devices: devList,
        running_flows: 5, memory_usage_mb: mem, status: 'online', ts: now
    }),
    qos: 1, retain: false
};

// === HTTP Heartbeat (async) ===
// === #88: 健康指标（PG 写入统计 + 磁盘 spool 积压）===
var pgSuccess = global.get('edge_pg_success_count') || 0;
var pgFail = global.get('edge_pg_fail_count') || 0;
var spoolBytes = 0;
try {
    var _fs = global.get('fs');
    var _path = global.get('path');
    if (_fs && _path) {
        var spoolDir = _path.join(global.get('userDir') || '.', 'edgelink_pg_spool');
        if (_fs.existsSync(spoolDir)) {
            _fs.readdirSync(spoolDir).forEach(function (fname) {
                try { spoolBytes += _fs.statSync(_path.join(spoolDir, fname)).size; } catch (e) {}
            });
        }
    }
} catch (e) { spoolBytes = 0; }

var params = 'host_pc_ip=' + encodeURIComponent(hostPcIp)
    + '&node_ip=' + encodeURIComponent(hostPcIp)
    + '&running_flows=5&memory_usage_mb=' + mem
    + '&pg_success_count=' + pgSuccess + '&pg_fail_count=' + pgFail + '&spool_bytes=' + spoolBytes
    + (global.get('edge_configVersion') ? '&config_version=' + global.get('edge_configVersion') : '');  // 🔧 捎带已应用快照版本

var hbOpts = {
    hostname: HOST, port: PORT, path: '/monitor/heartbeat?' + params, method: 'POST',
    headers: { 'X-API-Key': apiKey, 'Authorization': 'Bearer ' + jwt, 'Content-Type': 'application/json' }
};

var hbReq = http.request(hbOpts, function (res) {
    var b = '';
    res.on('data', function (d) { b += d; });
    res.on('end', function () {
        if (res.statusCode === 401 && !global.get('edge_reauthInProgress')) {
            node.warn('[Monitor] JWT expired (401), trigger re-login');
            global.set('edge_jwt', '');
            global.set('edge_configReady', false);
            global.set('edge_reauthInProgress', true);
            reauthNeeded = true;
        }
        try {
            var j = JSON.parse(b);
            var nid = (j.data && j.data.node_id) ? j.data.node_id : 0;
            if (nid > 0 && nid !== nodeId) {
                global.set('edge_nodeId', nid);
                if (DEBUG) node.warn('[Monitor] nodeId updated: ' + nodeId + ' → ' + nid);
            }
            // 🔧 Day7/P1-6: kill switch 轮询兜底——心跳响应携带 disabled 标志，每周期比对
            var disabledFlag = !!(j.data && j.data.disabled);
            var curDisabled = !!global.get('edge_nodeDisabled');
            if (disabledFlag !== curDisabled) {
                global.set('edge_nodeDisabled', disabledFlag);
                try {
                    var _fs2 = global.get('fs'); var _path2 = global.get('path');
                    if (_fs2 && _path2) {
                        var cf = _path2.join(global.get('userDir') || '.', 'edge_config_cache.json');
                        var cc = {};
                        if (_fs2.existsSync(cf)) { try { cc = JSON.parse(_fs2.readFileSync(cf, 'utf8')); } catch (e2) {} }
                        cc.disabled = disabledFlag;
                        _fs2.writeFileSync(cf, JSON.stringify(cc, null, 2));
                    }
                } catch (e3) {}
                if (disabledFlag) {
                    global.set('edge_devices', []);
                    global.set('edge_tagConfigs', {});
                    global.set('edge_configReady', false);
                    node.warn('[Monitor] ⚠ 本节点已被后端停用（心跳轮询发现），采集已停止');
                } else {
                    global.set('edge_configReady', false);
                    node.warn('[Monitor] ✅ 本节点已重新启用（心跳轮询发现），等待下轮配置刷新');
                }
            }
        } catch (e) {}
        reportAllDevicesOnline();
        node.status({ fill: res.statusCode === 200 ? 'green' : 'red', shape: 'dot', text: 'HB ' + res.statusCode });
        consumeDeviceComm(tryFinalSend);
        reportPgStats(tryFinalSend);
        tryFinalSend();
    });
});
hbReq.setTimeout(5000, function () {
    hbReq.destroy();
    reportAllDevicesOnline();
    consumeDeviceComm(tryFinalSend);
    reportPgStats(tryFinalSend);
    tryFinalSend();
});
hbReq.on('error', function (e) {
    if (DEBUG) node.warn('[Monitor] HB err: ' + e.message);
    reportAllDevicesOnline();
    consumeDeviceComm(tryFinalSend);
    reportPgStats(tryFinalSend);
    tryFinalSend();
});
hbReq.write('{}');
hbReq.end();

// === Device-comm consumer: drain edge_commPending (30s batch) ===
function consumeDeviceComm(done) {
    var pending = global.get('edge_commPending') || [];
    if (pending.length === 0) { return; }  // 🔧 Don't call done() — nothing to consume, doesn't count
    global.set('edge_commPending', []);
    pendingOps += pending.length;
    if (DEBUG) node.warn('[Monitor] Draining ' + pending.length + ' device-comm events');
    pending.forEach(function (item) {
        var itemDone = false;
        function itemFinish() {
            if (itemDone) return;
            itemDone = true;
            if (done) done();
        }
        var p = 'node_id=' + encodeURIComponent(nodeId) + '&device_id=' + encodeURIComponent(item.deviceId)
            + '&success=' + (item.success ? 'true' : 'false')
            + '&error_msg=' + encodeURIComponent(item.error || '');
        var opts = {
            hostname: HOST, port: PORT, path: '/monitor/device-comm?' + p, method: 'POST',
            headers: { 'X-API-Key': apiKey, 'Authorization': 'Bearer ' + jwt, 'Content-Type': 'application/json' }
        };
        var req = http.request(opts, function (res) {
            if (res.statusCode === 401 && !reauthNeeded) reauthNeeded = true;
            res.resume();
            itemFinish();
        });
        req.setTimeout(3000, function () { req.destroy(); itemFinish(); });
        req.on('error', function () { itemFinish(); });
        req.write('{}');
        req.end();
    });
}

// === PG Write Stats reporter ===
function reportPgStats(done) {
    pendingOps++;  // 🔧 P1: count this async op
    var pgDone = false;
    function pgFinish() {
        if (pgDone) return;
        pgDone = true;
        if (done) done();
    }
    var pgCount = global.get('edge_pg_success_count') || 0;
    var pgFailCount = global.get('edge_pg_fail_count') || 0;
    var pgPrev = global.get('edge_pg_prev_count') || 0;
    var pgFailPrev = global.get('edge_pg_fail_prev') || 0;
    var writeCount = pgCount - pgPrev;
    var failCount = pgFailCount - pgFailPrev;
    global.set('edge_pg_prev_count', pgCount);
    global.set('edge_pg_fail_prev', pgFailCount);
    var lastError = global.get('edge_pg_last_error') || '';
    var success = (failCount === 0);
    var p = 'node_id=' + encodeURIComponent(nodeId) + '&success=' + (success ? 'true' : 'false') + '&latency_ms=' + (global.get('edge_pg_last_latency_ms') || 5)
        + '&write_count=' + writeCount + '&device_count=' + devices.length + '&error_msg=' + encodeURIComponent(lastError);
    var opts = {
        hostname: HOST, port: PORT, path: '/monitor/pg-write?' + p, method: 'POST',
        headers: { 'X-API-Key': apiKey, 'Authorization': 'Bearer ' + jwt, 'Content-Type': 'application/json' }
    };
    var req = http.request(opts, function (res) {
        if (res.statusCode === 401 && !reauthNeeded) reauthNeeded = true;
        res.resume();
        pgFinish();
    });
    req.setTimeout(3000, function () { req.destroy(); pgFinish(); });
    req.on('error', function () { pgFinish(); });
    req.write('{}');
    req.end();
}

return null;
